22	import IndicatorAxis from './IndicatorAxis';
23	import IntervalScale from '../../scale/Interval';
24	import * as numberUtil from '../../util/number';
25	import { CoordinateSystemMaster, CoordinateSystem } from '../CoordinateSystem';
26	import RadarModel from './RadarModel';
27	import GlobalModel from '../../model/Global';
28	import ExtensionAPI from '../../core/ExtensionAPI';
29	import { ScaleDataValue } from '../../util/types';
30	import { ParsedModelFinder } from '../../util/model';
31	import { map, each, isString, isNumber } from 'zrender/src/core/util';
32	import { alignScaleTicks } from '../axisAlignTicks';
33	import { createBoxLayoutReference } from '../../util/layout';
