35	
36	class Radar implements CoordinateSystem, CoordinateSystemMaster {
37	
38	    readonly type: 'radar';
39	    /**
40	     *
41	     * Radar dimensions
42	     */
43	    readonly dimensions: string[] = [];
44	
45	    cx: number;
46	
47	    cy: number;
48	
49	    r: number;
50	
51	    r0: number;
52	
53	    startAngle: number;
54	
55	    private _model: RadarModel;
56	
57	    private _indicatorAxes: IndicatorAxis[];
58	
59	    constructor(radarModel: RadarModel, ecModel: GlobalModel, api: ExtensionAPI) {
60	        this._model = radarModel;
61	
62	        this._indicatorAxes = map(radarModel.getIndicatorModels(), function (indicatorModel, idx) {
63	            const dim = 'indicator_' + idx;
64	            const indicatorAxis = new IndicatorAxis(dim,
65	                new IntervalScale()
66	                // (indicatorModel.get('axisType') === 'log') ? new LogScale() : new IntervalScale()
67	            );
68	            indicatorAxis.name = indicatorModel.get('name');
69	            // Inject model and axis
70	            indicatorAxis.model = indicatorModel;
71	            indicatorModel.axis = indicatorAxis;
72	            this.dimensions.push(dim);
73	            return indicatorAxis;
74	        }, this);
75	
76	        this.resize(radarModel, api);
77	    }
78	
79	    getIndicatorAxes() {
80	        return this._indicatorAxes;
81	    }
82	
83	    dataToPoint(value: ScaleDataValue, indicatorIndex: number) {
84	        const indicatorAxis = this._indicatorAxes[indicatorIndex];
85	
86	        return this.coordToPoint(indicatorAxis.dataToCoord(value), indicatorIndex);
87	    }
88	
89	    // TODO: API should be coordToPoint([coord, indicatorIndex])
90	    coordToPoint(coord: number, indicatorIndex: number) {
91	        const indicatorAxis = this._indicatorAxes[indicatorIndex];
92	        const angle = indicatorAxis.angle;
93	        const x = this.cx + coord * Math.cos(angle);
94	        const y = this.cy - coord * Math.sin(angle);
95	        return [x, y];
96	    }
97	
98	    pointToData(pt: number[]) {
99	        let dx = pt[0] - this.cx;
100	        let dy = pt[1] - this.cy;
101	        const radius = Math.sqrt(dx * dx + dy * dy);
102	        dx /= radius;
103	        dy /= radius;
104	
105	        const radian = Math.atan2(-dy, dx);
106	
107	        // Find the closest angle
108	        // FIXME index can calculated directly
109	        let minRadianDiff = Infinity;
110	        let closestAxis;
111	        let closestAxisIdx = -1;
112	        for (let i = 0; i < this._indicatorAxes.length; i++) {
113	            const indicatorAxis = this._indicatorAxes[i];
114	            const diff = Math.abs(radian - indicatorAxis.angle);
115	            if (diff < minRadianDiff) {
116	                closestAxis = indicatorAxis;
117	                closestAxisIdx = i;
118	                minRadianDiff = diff;
119	            }
120	        }
121	
122	        return [closestAxisIdx, +(closestAxis && closestAxis.coordToData(radius))];
123	    }
124	
125	    resize(radarModel: RadarModel, api: ExtensionAPI) {
126	        const refContainer = createBoxLayoutReference(radarModel, api).refContainer;
127	
128	        const center = radarModel.get('center');
129	        const viewSize = Math.min(refContainer.width, refContainer.height) / 2;
130	        this.cx = numberUtil.parsePercent(center[0], refContainer.width) + refContainer.x;
131	        this.cy = numberUtil.parsePercent(center[1], refContainer.height) + refContainer.y;
132	
133	        this.startAngle = radarModel.get('startAngle') * Math.PI / 180;
134	
135	        // radius may be single value like `20`, `'80%'`, or array like `[10, '80%']`
136	        let radius = radarModel.get('radius');
137	        if (isString(radius) || isNumber(radius)) {
138	            radius = [0, radius];
139	        }
140	        this.r0 = numberUtil.parsePercent(radius[0], viewSize);
141	        this.r = numberUtil.parsePercent(radius[1], viewSize);
142	
143	        each(this._indicatorAxes, function (indicatorAxis, idx) {
144	            indicatorAxis.setExtent(this.r0, this.r);
145	            let angle = (this.startAngle + idx * Math.PI * 2 / this._indicatorAxes.length);
146	            // Normalize to [-PI, PI]
147	            angle = Math.atan2(Math.sin(angle), Math.cos(angle));
148	            indicatorAxis.angle = angle;
149	        }, this);
150	    }
151	
152	    update(ecModel: GlobalModel, api: ExtensionAPI) {
153	        const indicatorAxes = this._indicatorAxes;
154	        const radarModel = this._model;
155	        each(indicatorAxes, function (indicatorAxis) {
156	            indicatorAxis.scale.setExtent(Infinity, -Infinity);
157	        });
158	        ecModel.eachSeriesByType('radar', function (radarSeries, idx) {
159	            if (radarSeries.get('coordinateSystem') !== 'radar'
160	                // @ts-ignore
161	                || ecModel.getComponent('radar', radarSeries.get('radarIndex')) !== radarModel
162	            ) {
163	                return;
164	            }
165	            const data = radarSeries.getData();
166	            each(indicatorAxes, function (indicatorAxis) {
167	                indicatorAxis.scale.unionExtentFromData(data, data.mapDimension(indicatorAxis.dim));
168	            });
169	        }, this);
170	
171	        const splitNumber = radarModel.get('splitNumber');
172	        const dummyScale = new IntervalScale();
173	        dummyScale.setExtent(0, splitNumber);
174	        dummyScale.setInterval(1);
175	        // Force all the axis fixing the maxSplitNumber.
176	        each(indicatorAxes, function (indicatorAxis, idx) {
177	            alignScaleTicks(
178	                indicatorAxis.scale as IntervalScale,
179	                indicatorAxis.model,
180	                dummyScale
181	            );
182	        });
183	    }
184	
185	    convertToPixel(ecModel: GlobalModel, finder: ParsedModelFinder, value: ScaleDataValue[]): never {
186	        console.warn('Not implemented.');
187	        return null as never;
188	    }
189	    convertFromPixel(ecModel: GlobalModel, finder: ParsedModelFinder, pixel: number[]): never {
190	        console.warn('Not implemented.');
191	        return null as never;
192	    }
193	    containPoint(point: number[]): boolean {
194	        console.warn('Not implemented.');
195	        return false;
196	    }
197	    /**
198	     * Radar dimensions is based on the data
199	     */
200	    static dimensions: string[] = [];
201	
202	    static create(ecModel: GlobalModel, api: ExtensionAPI) {
203	        const radarList: Radar[] = [];
204	        ecModel.eachComponent('radar', function (radarModel: RadarModel) {
205	            const radar = new Radar(radarModel, ecModel, api);
206	            radarList.push(radar);
207	            radarModel.coordinateSystem = radar;
208	        });
209	        ecModel.eachSeriesByType('radar', function (radarSeries) {
210	            if (radarSeries.get('coordinateSystem') === 'radar') {
211	                // Inject coordinate system
212	                // @ts-ignore
213	                radarSeries.coordinateSystem = radarList[radarSeries.get('radarIndex') || 0];
214	            }
215	        });
216	        return radarList;
217	    }
218	}
219	
220	
221	export default Radar;
