106	    optionUpdated() {
107	        const boundaryGap = this.get('boundaryGap');
108	        const splitNumber = this.get('splitNumber');
109	        const scale = this.get('scale');
110	        const axisLine = this.get('axisLine');
111	        const axisTick = this.get('axisTick');
112	        // let axisType = this.get('axisType');
113	        const axisLabel = this.get('axisLabel');
114	        const nameTextStyle = this.get('axisName');
115	        const showName = this.get(['axisName', 'show']);
116	        const nameFormatter = this.get(['axisName', 'formatter']);
117	        const nameGap = this.get('axisNameGap');
118	        const triggerEvent = this.get('triggerEvent');
119	
120	        const indicatorModels = zrUtil.map(this.get('indicator') || [], function (indicatorOpt) {
121	            // PENDING
122	            if (indicatorOpt.max != null && indicatorOpt.max > 0 && !indicatorOpt.min) {
123	                indicatorOpt.min = 0;
124	            }
125	            else if (indicatorOpt.min != null && indicatorOpt.min < 0 && !indicatorOpt.max) {
126	                indicatorOpt.max = 0;
127	            }
128	            let iNameTextStyle = nameTextStyle;
129	            if (indicatorOpt.color != null) {
130	                iNameTextStyle = zrUtil.defaults({
131	                    color: indicatorOpt.color
132	                }, nameTextStyle);
133	            }
134	            // Use same configuration
135	            const innerIndicatorOpt: InnerIndicatorAxisOption = zrUtil.merge(zrUtil.clone(indicatorOpt), {
136	                boundaryGap: boundaryGap,
137	                splitNumber: splitNumber,
138	                scale: scale,
139	                axisLine: axisLine,
140	                axisTick: axisTick,
141	                // axisType: axisType,
142	                axisLabel: axisLabel,
143	                // Compatible with 2 and use text
144	                name: indicatorOpt.text,
145	                showName: showName,
146	                nameLocation: 'end',
147	                nameGap: nameGap,
148	                // min: 0,
149	                nameTextStyle: iNameTextStyle,
150	                triggerEvent: triggerEvent
151	            } as InnerIndicatorAxisOption, false);
152	            if (zrUtil.isString(nameFormatter)) {
153	                const indName = innerIndicatorOpt.name;
154	                innerIndicatorOpt.name = nameFormatter.replace('{value}', indName != null ? indName : '');
155	            }
156	            else if (zrUtil.isFunction(nameFormatter)) {
157	                innerIndicatorOpt.name = nameFormatter(
158	                    innerIndicatorOpt.name, innerIndicatorOpt
159	                );
160	            }
161	
162	            const model = new Model(innerIndicatorOpt, null, this.ecModel) as AxisBaseModel<InnerIndicatorAxisOption>;
163	            zrUtil.mixin(model, AxisModelCommonMixin.prototype);
164	            // For triggerEvent.
165	            model.mainType = 'radar';
166	            model.componentIndex = this.componentIndex;
167	
168	            return model;
169	        }, this);
170	
171	        this._indicatorModels = indicatorModels;
172	    }
